const course: DeepCourse = {"slug":"ai-marketing-and-aeo","title":"AI Marketing & AEO.","premium":true,"previewCount":3,"chunks":[{"kind":"html","value":"<section class=\"px-5 pt-28 md:px-8 md:pt-40\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Career skill · Pro</p><h1 class=\"display-lg mt-4\">AI Marketing &amp; AEO<span class=\"dot\" aria-hidden=\"true\">.</span></h1><p class=\"lede mt-5 max-w-xl\">Use ChatGPT and Claude like a professional, and learn AEO — getting clients cited inside AI answers — before most agencies have.</p><div class=\"mt-8\"><div class=\"flex flex-wrap items-center gap-2.5\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Premium course</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">8 modules</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">4h 40m of reading and doing</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">8 portfolio pieces</span></div><p class=\"mt-4 mb-2 text-[0.8125rem] text-muted\">Course content is based on active job listings and industry hiring patterns. These are practical guides, not formal certifications.</p></div></div></section><nav aria-label=\"Course sections\" class=\"sticky top-16 z-20 border-b border-line bg-paper/90 backdrop-blur-md\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-6xl\"><ul class=\"-mx-1 flex gap-1 overflow-x-auto py-2.5 [scrollbar-width:none] [&amp;::-webkit-scrollbar]:hidden\"><li><a href=\"#the-job\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">The job</a></li><li><a href=\"#tools\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Tools</a></li><li><a href=\"#modules\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Modules</a></li><li><a href=\"#keep-learning\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Resources</a></li><li><a href=\"#rates\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Rates</a></li><li><a href=\"#first-client\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">First client</a></li><li><a href=\"#quiz\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Quiz</a></li><li><a href=\"#glossary\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Glossary</a></li><li><a href=\"#red-flags\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Red flags</a></li><li><a href=\"#faq\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">FAQ</a></li></ul></div></nav><section class=\"px-5 pt-10 md:px-8\"><div class=\"mx-auto max-w-5xl\"><div id=\"plain-words\" class=\"rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><p class=\"eyebrow\">In plain words</p><p class=\"mt-3 max-w-3xl text-[1.0625rem] leading-[1.75] text-ink\">Two skills in one. First: using ChatGPT and Claude properly — prompts, quality control, honest workflows. Second: AEO, the brand-new work of getting a business mentioned inside AI answers like Google’s AI Overviews. It’s new enough that you can genuinely get ahead of agencies.</p><div class=\"mt-6 grid gap-5 sm:grid-cols-2\"><div><p class=\"eyebrow text-muted\">This is for you if</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">You’re curious about AI but tired of the hype. You want the practical version, with the risks handled.</p></div><div><p class=\"eyebrow text-muted\">You walk away with</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">A prompt library, a fact-checked content pipeline, an AI-citable page brief, and a measurement plan — assembled into one portfolio system in the capstone.</p></div></div></div></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"the-job\" class=\"scroll-mt-32\"><div class=\"space-y-5\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">Every client is being sold AI right now — by tools, by agencies, by their nephew. Almost none of them have someone who can run it calmly: good prompts, verified facts, honest reporting. That person gets paid more than the person who types faster.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">This track teaches two connected skills. First, AI-assisted marketing execution: prompting, content pipelines with the fact-check built in, and small safe automations. Second, AEO — answer engine optimisation — the work of making a business the source that Google’s AI Overviews, ChatGPT and Perplexity actually cite. The second skill is brand new, agencies are still improvising it, and a VA who can do it credibly is very hard to replace.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">You will work on the same fictional client as the SEO track: Baler Coffee Roasters in Quezon City. If you took that track, this one builds on it. If you did not, everything you need is explained where it appears.</p></div><dl class=\"mt-10 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Also posted as</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">AI content VA, AI marketing assistant, GEO/AEO specialist, marketing automation VA</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Core loop</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Brief → prompt → draft → verify → publish → measure → report</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Pays more than general VA by</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Roughly 30–60% at the same experience level, more with automation setup work</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Hardest part</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Telling a client their 20-posts-a-week plan will hurt them, and having the workflow to prove it</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Easiest way in</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">A documented content system with a fact-check log — module 8 builds exactly that</dd></div></dl></section><section class=\"mt-16\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What a shift actually looks like</h2><ol class=\"mt-6 space-y-0\"><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Start of shift</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Draft queue review</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Approve, edit or bounce the AI drafts your pipeline produced overnight. Nothing publishes unread.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Morning block</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Deep work: briefs and citable pages</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Write the AEO briefs and restructure pages while your judgment is fresh.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Mid-shift</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Production runs</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Run the prompt library: posts, captions, review replies. Fact-check as you go, log as you finish.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Weekly</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Automation check</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Read the automation logs, fix what tool updates broke, note time saved for the report.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Monthly</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">AI visibility report</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Run the tracked query set, log citations won and lost, write the three next moves.</p></div></li></ol></section></div><section id=\"tools\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">The tools, and why each one exists</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">The free tiers cover this entire course. Learn the workflow first; upgrade only when a client’s volume demands it.</p><div class=\"mt-8 space-y-8\"><div><p class=\"eyebrow text-muted\">Non-negotiable, and free</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">ChatGPT</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The model most clients already talk about. Learn its strengths and its confident lies first.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Claude</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Stronger long-document work and tone matching. Your second opinion on every important draft.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Search Console</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Where the second-order AEO signals show up: branded impressions, query changes.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Sheets</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The prompt library, the fact-check log, the query tracker. The system lives here.</p></li></ul></div><div><p class=\"eyebrow text-muted\">Understand before you need them</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Zapier / Make / n8n</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The wiring for module 6’s draft-only automations. n8n is the free-forever self-hosted option.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Semrush / Ahrefs</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Both now track AI Overview presence. Use the client’s licence; know the vocabulary before the interview.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Perplexity</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The assistant that shows its citations openly — the best free window into how retrieval picks sources.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Schema validator</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">validator.schema.org — check every piece of markup you ship against what the page visibly says.</p></li></ul></div></div></div></section>"},{"kind":"slot","value":"MODULES","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"keep-learning\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Keep learning<span class=\"dot\" aria-hidden=\"true\">.</span></h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Hand-picked and free. These open in a new tab — official docs, academies and channels that go deeper on what this track teaches. No affiliate links, no sign-up walls.</p><div class=\"mt-8\"><p class=\"eyebrow text-muted\">Watch first</p><div class=\"mt-3.5 grid gap-4 sm:grid-cols-2\"><div class=\"overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"aspect-video\"><iframe class=\"h-full w-full\" src=\"https://www.youtube-nocookie.com/embed/TIypxl5_v5Y\" title=\"Generative engine optimization, explained\" loading=\"lazy\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe></div><div class=\"px-4 py-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Generative engine optimization, explained</p><p class=\"mt-0.5 text-[0.8125rem] text-muted\">Semrush · YouTube</p></div></div></div></div><ul class=\"mt-8 grid gap-3 sm:grid-cols-2\"><li class=\"h-full\"><a href=\"https://developers.google.com/search/docs/fundamentals/ai-optimization-guide\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google’s AI features optimization guide</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The official word on AI Overviews and AI Mode. Short, and it debunks most paid GEO advice.</p></a></li><li class=\"h-full\"><a href=\"https://ahrefs.com/blog/geo-generative-engine-optimization/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Ahrefs — GEO strategies and metrics</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Data-backed numbers on AI Overviews you can quote in client reports.</p></a></li><li class=\"h-full\"><a href=\"https://platform.openai.com/docs/guides/prompt-engineering\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">OpenAI prompt engineering guide</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">First-party prompting techniques — the source behind most paid prompt courses.</p></a></li><li class=\"h-full\"><a href=\"https://docs.anthropic.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Anthropic docs — prompting with Claude</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The other first-party guide. The overlap between the two is the real curriculum.</p></a></li><li class=\"h-full\"><a href=\"https://developers.google.com/search/docs/fundamentals/seo-starter-guide\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google SEO Starter Guide</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">AEO sits on SEO. This is the baseline the retrieval step judges you against.</p></a></li><li class=\"h-full\"><a href=\"https://validator.schema.org/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Schema.org validator</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Paste a URL, check the markup. Use it on every page you touch in module 5.</p></a></li></ul></section></div>"},{"kind":"html","value":"<section class=\"border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><section id=\"rates\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What this actually pays</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Ranges assembled from 2026 OnlineJobs.ph listings for AI content and marketing automation roles, cross-checked against agency rate cards. The spread depends on whether you execute prompts or own a system with a report attached.</p><div class=\"mt-7 rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><div class=\"space-y-7\"><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Beginner</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">5–7<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:20%;width:15%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Running someone else’s prompt library, caption production, draft queues under review.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 800–1,120/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Intermediate</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">8–14<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:33%;width:25%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Owning the pipeline end to end: briefs, fact-check, publishing, the monthly report.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 1,280–2,240/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Specialist</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">15–25<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:55%;width:40%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">AEO strategy, automation builds with maintenance retainers, and reporting a founder forwards to investors.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 2,400–4,000/mo full-time</p></div></div></div></div><p class=\"mt-4 text-[0.8125rem] leading-relaxed text-muted\">Setup projects (prompt library + one automation) commonly go for $300–800 flat on top of hourly work.</p></section><section id=\"first-client\" class=\"mt-16 scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Landing the first client</h2><ol class=\"mt-6 space-y-0\"><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Week 1</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Build the capstone for a real business</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Do module 8 for an actual local business — unasked. The folder is your portfolio; the Loom is your pitch.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Week 2</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Send it to that business</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Short message: here is a system I built around your content, here is the five-minute walkthrough, want the library?</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Weeks 2–3</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Apply with the artefact, not adjectives</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">On job posts, skip &#x27;proficient in ChatGPT&#x27;. Link the folder and say &#x27;I caught three factual errors AI made about your industry; here is the log.&#x27;</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Ongoing</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Let the report renew the contract</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">The monthly AI-visibility section is the retention engine — it shows movement nobody else is even measuring.</p></div></li></ol></section></div></section>"},{"kind":"slot","value":"QUIZ","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":""},{"kind":"slot","value":"GLOSSARY","wrappers":[{"tag":"section","class":"border-y border-line bg-paper-2/70 py-14 sm:py-20"},{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"red-flags\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Walk away when you see these</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Not every one is a scam. Some are just engagements that end with your name on someone else’s mess.</p><ul class=\"mt-7 space-y-3\"><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>&#x27;We need 100 posts a month, no review step&#x27;</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Volume without verification publishes hallucinations at scale. When one goes viral for being wrong, the VA is the first name mentioned.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>&#x27;Use AI to write our reviews / testimonials&#x27;</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Fake reviews are illegal in the client’s market and yours. This client will also lie to you about payment.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>&#x27;Guarantee ChatGPT recommends us&#x27;</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Nobody controls model outputs per user. You can improve citation odds and measure honestly — anyone guaranteeing placement is lying.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Medical, legal or financial content with no expert reviewer</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">YMYL content needs a qualified human sign-off. AI-drafting it without one risks real harm and real liability.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>&#x27;Pass it off as our in-house expert’s writing&#x27; in expertise niches</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Ghost-writing is normal; fabricating credentials and first-hand experience is not. E-E-A-T fraud eventually gets caught by readers or by Google.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>No access to analytics or Search Console</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">You cannot measure AI visibility or anything else. A client who withholds data wants deliverables, not outcomes — priced accordingly or declined.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Pay per AI-generated word</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">The unit is wrong. Words are free now; verification, judgment and systems are what you sell. Per-word AI pricing races to the bottom by design.</p></li></ul></section><section id=\"faq\" class=\"mt-16 scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Questions people actually ask</h2><dl class=\"mt-7 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Do I need the SEO track first?</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">No, but they compound. AEO sits on top of SEO — if you plan to do both, the SEO track first is the better order.</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Will AI take this job?</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">AI took the typing. The judgment — briefs, verification, systems, honest reporting — got more valuable, not less. That is what this track teaches.</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Do I need paid tools?</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">No. Free tiers of ChatGPT, Claude and Perplexity plus Google’s free stack cover every module including the capstone.</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Is AEO real or a fad acronym?</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">The acronym will churn; the work is durable. AI answers cite sources, someone decides how citable a business is, and clients pay that someone.</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Can I sell this to Filipino businesses too?</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Yes — local businesses are being pitched AI constantly and trust a calm, honest operator. The capstone works for a Manila café exactly as well as a US client.</dd></div></dl></section></div>"}],"modules":[{"n":1,"title":"What AI actually changed (and what it did not)","minutes":25,"outcome":"You can explain to a client which of their marketing tasks AI genuinely speeds up, which it quietly ruins, and where you fit.","badges":["Foundations","Client conversations"],"html":"<div class=\"space-y-6\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">The AI-literate VA is not competing with ChatGPT. You are competing with VAs who either refuse to use it or paste its output unread. Both lose. The job clients are actually hiring for in 2026 is judgment: knowing what to ask, what to keep, and what to catch before it publishes.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">Large language models — ChatGPT, Claude, Gemini — predict text. They are extraordinary at structure, tone, summarising, reformatting and first drafts. They are unreliable at facts, numbers, names and anything that happened recently, and they will state a wrong answer with the same confidence as a right one. That failure mode has a name, hallucination, and managing it is most of the professional skill.</p><div class=\"mt-4\"><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:42rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Task</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">AI alone</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">VA + AI</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Why</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">First draft of a blog post</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Generic, confident, sometimes wrong</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Strong</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">You supply the brief, the facts and the edit. AI supplies speed.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Client’s monthly report numbers</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Dangerous</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">AI drafts the commentary only</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Numbers come from the source. AI never touches them unverified.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Social caption variations</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Fine</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Faster and on-brand</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Low-stakes, high-volume. Perfect AI territory with a tone example.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Legal, medical, financial claims</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Never</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Human sources, AI polishes wording</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">One made-up statistic in a YMYL niche can end the client’s business.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Research on a new market</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Starting point only</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">AI maps the terrain, you verify</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Every claim needs a primary source before it reaches the client.</td></tr></tbody></table></div></div></div><ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Say &#x27;AI-assisted&#x27; honestly. Most clients now expect it; the ones who forbid it are telling you something useful about the engagement.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The market shifted, not shrank: fewer &#x27;write 10 articles&#x27; jobs, more &#x27;run our content system&#x27; jobs. Systems pay better than articles.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Free tiers of ChatGPT and Claude are enough for this whole course. Do not buy anything yet.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Take a real business you know and list ten of its recurring marketing tasks. Sort each into: AI-safe, AI-with-review, human-only. Write one sentence per row justifying the sort.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: The ten-row sorted list with justifications.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 40 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every AI-safe row is genuinely low-stakes if the output is mediocre</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">At least two rows are human-only, with the risk named</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You could defend each sort to a sceptical client</span></label></li></ul></div></div>"},{"n":2,"title":"Prompting like a professional","minutes":35,"outcome":"You can turn a vague client request into a prompt that produces a usable draft on the first or second try.","badges":["Workflow","1 template"],"html":"<div class=\"space-y-6\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">A prompt is a brief. Everything you already know about briefing a writer applies: audience, purpose, format, tone, length, examples, and what to avoid. Vague briefs produce vague drafts, from humans and models alike.</p><ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Be precise about the deliverable. &#x27;Write a blog intro&#x27; is a wish. &#x27;Write a 120-word intro for Filipino freelancers who already know what SEO is, ending with a question&#x27; is a brief.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Name the audience and what they already know. The single biggest quality lever in any prompt.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Give it a role and a tone example. Two sentences of the client’s actual writing beats any adjective list.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Constrain the format: word count, structure, headings, what to exclude. Models follow structure instructions well.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Iterate instead of restarting. &#x27;Keep the structure, make paragraph two more specific, remove the clichés&#x27; is the real workflow.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Save what works. A prompt library is a genuine client deliverable — agencies bill for them.</span></li></ul><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">The brief → prompt → edit loop</h4><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Baler Coffee blog intro, second pass</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">v1 prompt → &#x27;write an intro about storing coffee beans&#x27; → generic, could be any site</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">v2 prompt → role + audience (QC coffee buyers) + tone sample + 120 words + end on a question</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">v2 output → usable after a two-minute edit: one cliché cut, one local detail added</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">saved to library as &#x27;blog-intro.md&#x27; with a note on what the tone sample was</p></div></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Reusable content prompt (fill the brackets)</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Works in ChatGPT, Claude and Gemini. Keep one per content type in your library.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>You are [role: e.g. a content writer for a specialty coffee roaster in Quezon City].\n\nAudience: [who they are and what they already know]\nTask: [exact deliverable, e.g. a 120-word blog introduction about X]\nTone: match this sample of our writing: &quot;[paste 2–3 sentences]&quot;\nMust include: [facts, keywords, the one point that matters]\nMust avoid: [clichés, competitor names, claims we can’t back]\nFormat: [structure, length, headings]\n\nIf any information you need is missing, ask me instead of inventing it.</code></pre></div><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Pick one real piece of content you have seen a client publish. Reverse-engineer the brief, write the prompt using the template, run it, then iterate twice. Keep all three outputs.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: The prompt, the three outputs, and two sentences on what each iteration fixed.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Your prompt names audience, tone, format and exclusions</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The final output needed less than five minutes of hand editing</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The last line of the template (ask, don’t invent) is still in your prompt</span></label></li></ul></div></div>"},{"n":3,"title":"A content workflow that keeps quality","minutes":35,"outcome":"You can run an AI-assisted content pipeline a client can trust, with the fact-check built in rather than promised.","badges":["Workflow","Quality control"],"html":"<div class=\"space-y-6\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">Speed without a checking stage is just faster mistakes. The workflow below is what separates a VA who &#x27;uses ChatGPT&#x27; from one who runs a content operation.</p><div class=\"mt-4\"><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:44rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Stage</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Who does it</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Time</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What can go wrong here</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">1 · Brief</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">You, with the client</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">15 min</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Skipping it. The model fills every gap you leave with generic filler.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">2 · Outline</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">AI drafts, you approve</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">10 min</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Approving an outline that answers the wrong search intent.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">3 · Draft</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">AI</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">5 min</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Nothing — this is the safe part. Generate two versions.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">4 · Fact-check</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">You, against primary sources</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">20 min</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">The stage everyone skips. Every number, name, date and claim gets a source or gets cut.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">5 · Humanise</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">You</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">15 min</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Leaving the tells: &#x27;delve&#x27;, &#x27;in today’s fast-paced world&#x27;, perfectly parallel paragraphs, no opinions.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">6 · Publish + log</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">You</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">10 min</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Not logging the prompt and sources. The log is what makes the system saleable.</td></tr></tbody></table></div></div></div><ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Fact-check against primary sources, not against the model. Asking the same model &#x27;are you sure?&#x27; is not verification.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Keep a kill list of AI tells for the client’s niche and edit them out on every pass.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">One honest disclosure line in your contract — &#x27;drafts are AI-assisted, every fact is human-verified&#x27; — prevents the awkward conversation later.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A 75-minute pipeline producing a verified article is the honest pitch. Anyone promising 20 articles a day is selling the mistakes stage.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — the fact-check log for one Baler Coffee post</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">claim: &#x27;beans stale within 2–4 weeks of roasting&#x27; → verified, two roaster sources linked</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">claim: &#x27;the Philippines is the world’s 4th largest coffee producer&#x27; → WRONG, cut (model invention)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">claim: &#x27;freezing beans is fine if airtight&#x27; → verified with caveat, rewritten to include it</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">log saved next to the draft → client can audit any line</p></div></div><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Run the full six-stage pipeline on one 600-word post for any real local business. Time each stage honestly.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: The published-ready post, the fact-check log, and your six timings.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 75 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every retained claim in the log has a primary source link</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">At least one AI claim was caught and cut — if none, check harder</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Total time is under two hours; note which stage you can compress next time</span></label></li></ul></div></div>"},{"n":4,"title":"AEO: how AI answers choose their sources","minutes":30,"outcome":"You understand where AI Overviews, ChatGPT and Perplexity get their answers, and why classic SEO is still the entry ticket.","badges":["AEO","How it works"],"html":"<div class=\"space-y-6\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">A growing share of searches now ends in an AI-written answer instead of ten blue links. Answer Engine Optimisation — AEO, also sold as GEO — is the work of making sure your client is the source that answer cites. The good news for you: it is mostly rigorous SEO wearing a new name.</p><ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">AI assistants do not know the live web. They use RAG — retrieval augmented generation: search first (Google, Bing), then write an answer from what they retrieved. If a page cannot rank, it cannot be retrieved; if it cannot be retrieved, it cannot be cited.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Google’s AI Overviews pull from the same index as normal search. There is no separate &#x27;AI index&#x27; to optimise for, and Google says so in its official guidance.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">When an AI Overview appears, clicks to the pages below it drop sharply. The client strategy shifts from &#x27;win the click&#x27; to &#x27;be the citation&#x27; — the brand named inside the answer.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">AI answers fan the query out into related sub-questions and pull sources per sub-question. Pages that answer a cluster of related questions win more citations than pages chasing one keyword.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The most-cited domains in AI answers are heavyweights like YouTube and Reddit. A presence there is now part of search strategy, not a separate channel.</span></li></ul><div class=\"mt-4\"><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:40rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Surface</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Where its answers come from</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What gets you cited</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Google AI Overviews</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Google’s own index</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Ranking + answer-first formatting + structured data</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">ChatGPT (browsing)</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Bing retrieval + training data</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Bing indexing, brand mentions across the web</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Perplexity</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Live retrieval, citations shown</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Clear, factual pages that answer one question fully</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Gemini</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Google index</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Same playbook as AI Overviews</td></tr></tbody></table></div></div></div><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — why Baler Coffee lost the click but won the customer</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">query → &#x27;how long do coffee beans stay fresh&#x27; shows an AI Overview</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">overview cites balercoffee.ph/blog/store-coffee-beans as source 2 of 3</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">clicks to the post drop → but branded searches for &#x27;baler coffee&#x27; rise that month</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">report line → &#x27;we are the named source in the answer 6,000 people read&#x27;</p></div></div><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Run ten real searches in your client’s (or any local business’s) niche. Record which trigger AI Overviews, which sources get cited, and whether the business appears anywhere in the chain.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A ten-row sheet: query, AI answer shown?, cited sources, client present?</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 40 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">At least three informational and three transactional queries tested</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every cited domain is logged, not just the client’s absence</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">One paragraph: where are the citations coming from in this niche?</span></label></li></ul></div></div>"},{"n":5,"title":"Making a client citable","minutes":40,"outcome":"You can restructure a page so both Google and AI assistants can lift the answer — and attribute it to your client.","badges":["AEO","On-page","1 template"],"html":"<div class=\"space-y-6\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">AI answers are assembled from pages that make extraction easy. Buried answers get skipped; clear ones get cited. This module is the on-page work of AEO, and it doubles as good SEO everywhere else.</p><ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Answer first. The question the page targets gets answered plainly in the first 40–60 words under the heading. Context and nuance come after, not before.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">One page, one question cluster. Cover the sub-questions AI fans out to — cost, how long, alternatives, is it worth it — as their own H2s.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use existing structured data: FAQ, Article, Product, Review, LocalBusiness. Google is explicit that no new AI-specific schema exists; anyone selling &#x27;AI schema&#x27; is selling smoke.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Show a named human. Author bylines, credentials, first-hand photos and honest experience are the E-E-A-T signals that separate citable pages from content farms.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Keep facts fresh and dated. AI features favour pages that state when a number was last checked.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Be present where AI already looks: a helpful YouTube video and honest Reddit participation in the niche often earn citations faster than another blog post.</span></li></ul><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">The citable-page checklist</h4><div class=\"mt-4\"><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:40rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Element</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Citable page</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Invisible page</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Opening</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Direct 40–60 word answer under the H1</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Three paragraphs of warm-up before the point</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Structure</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">H2 per sub-question, scannable</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">One 2,000-word wall of prose</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Evidence</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Named sources, dates, first-hand photos</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">&#x27;Studies show&#x27; with no study</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Author</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Real person, credentials, bio page</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Anonymous or &#x27;admin&#x27;</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Schema</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">FAQ/Article markup that matches the visible text</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">None, or markup for content that isn’t on the page</td></tr></tbody></table></div></div></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">AEO page brief (fill the brackets)</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Hand this to a writer — or to module 2’s prompt template — for any answer-first page.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Target question: [the exact question, as people ask it]\nDirect answer (40–60 words, goes right under the H1): [draft it first]\nSub-questions to cover as H2s: [3–6, from People Also Ask and AI answers]\nFacts to include, with sources: [each claim + primary source URL]\nAuthor: [named person + one-line credential]\nSchema: [FAQ / Article / LocalBusiness — matching visible content only]\nFreshness line: &quot;Last checked [month, year]&quot;</code></pre></div><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Take one existing page from a real business and rewrite its opening plus heading structure using the brief template. Do not write the whole page — restructure it.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: Before/after of the opening 100 words and the heading outline, plus the filled brief.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 50 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The direct answer survives being read out of context — that is how AI will use it</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every H2 maps to a sub-question someone actually asks</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">No schema is promised for content the page does not visibly contain</span></label></li></ul></div></div>"},{"n":6,"title":"AI agents and automations without the horror stories","minutes":35,"outcome":"You can set up small, safe automations — custom GPTs, Zapier steps — and know exactly which tasks must keep a human in the loop.","badges":["Automation","Tools"],"html":"<div class=\"space-y-6\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">The step past prompting is packaging: turning your best prompts into reusable assistants and wiring them into the tools a client already uses. Done small and reviewed, this is the highest-leverage hour you can sell. Done carelessly, it emails a hallucination to 4,000 subscribers.</p><ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A custom GPT (or a Claude project) is just your prompt library with a memory: the client’s tone guide, product facts and rules, saved once, reused by anyone on the team.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Zapier, Make and n8n connect triggers to actions: form submitted → draft reply; new review → draft response; article published → caption variants drafted.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The safety rule is one word: draft. Automations that draft for human review are safe. Automations that send are where the horror stories live.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Log everything the automation does. When the client asks &#x27;where did this reply come from&#x27;, you want an answer.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Price this as setup + a monthly &#x27;keep it working&#x27; retainer. Automations rot when tools update; maintenance is recurring revenue.</span></li></ul><div class=\"mt-4\"><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:42rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Task</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Automate?</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Design</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Review responses</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Draft only</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">New review → AI drafts in brand voice → human approves and posts</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Social captions from a blog post</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Yes, with review</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Publish → 5 caption variants to a Sheet → human picks</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Support email replies</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Draft only</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">AI suggests, human sends. Refunds and complaints: human writes.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Invoice amounts, prices, promises</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Never</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">No generated numbers reach a customer without a human check.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Weekly report commentary</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Draft only</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Numbers pulled by the tool, prose drafted by AI, verified by you</td></tr></tbody></table></div></div></div><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Baler Coffee’s review responder</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">trigger → new Google review lands</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">step 1 → AI drafts a reply: brand voice file + the review text + rules (no discounts, no arguing)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">step 2 → draft posts to a private Slack channel, never to Google</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">step 3 → owner taps approve or edits → you post it. Ten minutes saved per review, zero risk.</p></div></div><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Design (on paper — no tools needed) one draft-only automation for a real business: trigger, steps, the exact prompt, the review gate, and the log.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page automation spec a client could approve.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Nothing in the design sends anything without human approval</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The prompt includes the brand voice sample and the rules list</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You wrote down what breaks it — tool changes, weird inputs — and who notices</span></label></li></ul></div></div>"},{"n":7,"title":"Measuring AI visibility and reporting it","minutes":30,"outcome":"You can show a client whether AI answers mention them, track it monthly, and report it without overclaiming.","badges":["Reporting","Retention"],"html":"<div class=\"space-y-6\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">Clients keep paying for what they can see. AI visibility is new enough that most agencies report nothing — which makes a simple, honest monthly section your edge.</p><ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Build a fixed query set: 20–30 searches that matter to the client (their services, their questions, their brand). Same list every month, or the trend means nothing.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Track three things per query: does an AI answer appear, is the client cited or mentioned, and who else is. A spreadsheet is enough to start.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Watch the second-order signals in the tools you already have: branded search impressions in Search Console, direct traffic, &#x27;how did you hear about us&#x27; answers mentioning ChatGPT or Google’s answer.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Semrush and Ahrefs both track AI Overview presence now; use them when the client already pays, but never report a number you cannot explain.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Report honestly: AI answers vary by user and day. Frame results as &#x27;observed on our tracked set&#x27;, not as rankings.</span></li></ul><div class=\"mt-4\"><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:40rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Report section</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What goes in it</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cadence</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">AI answer presence</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">X of 25 tracked queries showed AI answers; client cited in Y</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Monthly</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Citation movement</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">New citations won and lost, with the page that earned them</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Monthly</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Second-order signals</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Branded impressions, direct traffic, attribution mentions</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Monthly</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Actions</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Three next moves, each tied to a finding above</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Monthly</td></tr></tbody></table></div></div></div><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — one honest report line</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">BAD → &#x27;We now rank #1 in ChatGPT&#x27; (not a thing; varies per user)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">GOOD → &#x27;On our 25-query set, AI answers appeared for 14; Baler was cited in 4,</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">        up from 1 last month. All three new citations point to the storage guide</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">        we restructured in module 5. Next: same treatment for the brewing page.&#x27;</p></div></div><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build the tracking sheet for a real business: 25 queries, run them once, log AI presence and citations, and write the four report sections for month zero.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: The sheet plus a half-page month-zero report.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 60 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Queries cover services, questions and the brand — not just one type</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every number in the report traces to a row in the sheet</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The actions section has three moves a client could approve tomorrow</span></label></li></ul></div></div>"},{"n":8,"title":"Capstone: the Baler Coffee AI content system","minutes":50,"outcome":"A portfolio piece: a documented, priced AI content system — prompt library, one citable page, one automation spec, one measurement plan.","badges":["Capstone","Portfolio"],"html":"<div class=\"space-y-6\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">Everything in one deliverable. You are handing Baler Coffee (or a real business you substitute) a system they could run without you — which is exactly why they will pay you to run it.</p><ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Part 1 — the prompt library: five prompts from module 2’s template (blog intro, full post, captions, review reply, report commentary), each with the tone sample embedded and a one-line usage note.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Part 2 — one citable page: a full AEO brief from module 5 plus the finished, fact-checked page using the module 3 pipeline, with the fact-check log attached.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Part 3 — one automation spec: the draft-only review responder (or your own), specced to module 6’s standard.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Part 4 — the measurement plan: the 25-query set and a month-zero baseline from module 7.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Part 5 — the one-page proposal: what the system does, what it costs monthly, and the honest line about AI assistance and human verification.</span></li></ul><div class=\"mt-4\"><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Part</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Time</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Proves to a client</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Prompt library</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">60 min</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">You have a system, not a habit</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Citable page + log</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">90 min</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">Quality control is built in, not promised</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Automation spec</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">45 min</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">You think about risk before tools</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Measurement plan</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">45 min</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">You expect to be held accountable</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Proposal</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">30 min</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2\">You can sell it — this is the page they forward to their partner</td></tr></tbody></table></div></div></div><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Assemble all five parts into one folder (Drive or Notion). Then record a five-minute Loom walking a pretend client through it.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: The folder link and the Loom. This pair is your interview answer to &#x27;what can you do with AI?&#x27;</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 270 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">A stranger could run the system from the folder alone</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The fact-check log shows at least one caught error</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The proposal names a monthly price and defends it in one sentence</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The Loom is under six minutes and never says &#x27;um, so basically&#x27;</span></label></li></ul></div></div>"}],"quiz":[{"q":"A client wants 20 AI-written articles published this week, no review step. What do you do?","options":["Deliver — the client is always right","Refuse to use AI at all","Propose the six-stage pipeline and show what the fact-check catches","Publish them but add a disclaimer"],"answer":2,"explain":"Volume without verification publishes hallucinations under the client’s name. Show the pipeline, show a caught error, and let the client choose speed with eyes open. Refusing AI entirely just loses you the client to someone worse."},{"q":"Why does a page that cannot rank in normal search almost never get cited by AI assistants?","options":["AI assistants only cite paid partners","They retrieve sources through search engines first (RAG), so unranked pages are never retrieved","AI assistants only read social media","They only cite pages with special AI schema"],"answer":1,"explain":"Assistants search first and write second — retrieval augmented generation. If the page is invisible to the retrieval step, it cannot appear in the answer. Classic SEO is the entry ticket to AEO."},{"q":"An AI Overview now appears above your client’s #1 ranking and clicks dropped. The honest strategic move is:","options":["Report the ranking and hide the click drop","Restructure the page answer-first so the client becomes the cited source inside the answer","Buy ads to compensate forever","Ask Google to remove the AI Overview"],"answer":1,"explain":"The Overview is not going away and you cannot opt a competitor’s query out of it. The winnable position is being the citation — answer-first structure, sub-question coverage, named author, honest sourcing."},{"q":"Which prompt will produce the most usable first draft?","options":["&#x27;Write a blog post about coffee storage&#x27;","&#x27;Write 800 words, SEO optimised, engaging, viral&#x27;","A prompt with audience, tone sample, format limits, required facts, and &#x27;ask instead of inventing&#x27;","The same request pasted five times for five options"],"answer":2,"explain":"A prompt is a brief. Audience, tone example, structure and exclusions are what the model can actually follow; adjectives like &#x27;engaging&#x27; and &#x27;viral&#x27; are noise."},{"q":"A vendor offers the client &#x27;proprietary AI schema markup that makes ChatGPT recommend you&#x27;. This is:","options":["A smart early-adopter move","Smoke — no AI-specific schema exists; existing types (FAQ, Article, Product) already serve AI features","Required by Google since 2025","Fine if it is cheap"],"answer":1,"explain":"Google’s own guidance says generative features use the same index and the same structured data types as regular search. Anyone selling secret AI markup is selling the client’s ignorance back to them."},{"q":"The AI draft says &#x27;the Philippines is the world’s 4th largest coffee producer&#x27;. Before publishing you:","options":["Keep it — it sounds plausible and specific","Ask the same model to confirm it","Find a primary source; if none exists, cut the claim","Soften it to &#x27;one of the largest&#x27; so it can’t be wrong"],"answer":2,"explain":"Models state inventions with full confidence, and asking the same model to check itself is not verification. Every number, name and date gets a primary source or gets cut — that log is your professional value."}],"glossary":[{"term":"LLM","def":"Large language model — ChatGPT, Claude, Gemini. Predicts text from patterns; brilliant at structure and tone, unreliable at facts."},{"term":"Prompt","def":"The instruction you give a model. Professionally: a brief, with audience, tone, format and exclusions."},{"term":"System prompt","def":"Standing instructions a model follows across a whole conversation or tool — where the brand voice and rules live."},{"term":"Token","def":"The unit models read and bill by; roughly three-quarters of a word in English."},{"term":"Context window","def":"How much text the model can consider at once. Paste more than it holds and the start silently falls out."},{"term":"Hallucination","def":"A confident, fluent, wrong statement. Not a rare glitch — a standing property you design the workflow around."},{"term":"AI Overviews","def":"Google’s AI-written answer above the results, assembled from the normal search index with sources cited."},{"term":"AEO","def":"Answer engine optimisation — the work of becoming the source AI answers cite. Also marketed as GEO or LLMO."},{"term":"GEO","def":"Generative engine optimisation. Same discipline as AEO, different acronym on the invoice."},{"term":"RAG","def":"Retrieval augmented generation: the assistant searches first, then writes from what it retrieved. Why ranking still matters."},{"term":"Entity","def":"A thing search engines recognise — a business, person, place. Consistent naming everywhere is how a small brand becomes one."},{"term":"Structured data","def":"Schema markup (FAQ, Article, Product, LocalBusiness) that labels page content for machines. No AI-specific type exists."},{"term":"E-E-A-T","def":"Experience, expertise, authoritativeness, trust — the qualities that separate citable pages from content farms."},{"term":"Query fan-out","def":"AI answers expand one question into related sub-questions and pull sources for each. Cover the cluster, win more citations."},{"term":"Zero-click search","def":"A search that ends on the results page. The metric shifts from clicks won to citations earned."},{"term":"Custom GPT","def":"A packaged assistant carrying your prompts, tone files and rules — a prompt library the whole team can use."}]} as DeepCourse;

export default course;
